-- 1. Deleting a user failed while a password reset token existed (foreign key without
--    ON DELETE). The constraint name was generated by Hibernate, so it is looked up.
DO $$
DECLARE
    fk_name TEXT;
BEGIN
    SELECT conname INTO fk_name
    FROM pg_constraint
    WHERE conrelid = 'password_reset_token'::regclass AND contype = 'f';

    IF fk_name IS NOT NULL THEN
        EXECUTE format('ALTER TABLE password_reset_token DROP CONSTRAINT %I', fk_name);
    END IF;
END $$;

ALTER TABLE password_reset_token
    ADD CONSTRAINT fk_password_reset_token_user
    FOREIGN KEY (user_id) REFERENCES users (id) ON DELETE CASCADE;

-- 2. Every itinerary query filters by owner.
CREATE INDEX IF NOT EXISTS idx_itineraries_user_id ON itineraries (user_id);
